import { useQueryClient } from '@tanstack/react-query';
import { figureToday } from '../../api/http';
import { HomeMain } from '../../slots/defs/homeMain';
import { sheetQueryKey, useCurrentSheet, useCurrentUser, type SheetInfo } from '../session/session';
import { peoplePath, peopleQueryKey, type Person } from '../people/people';
import { csvValue, readFresh, sheetInfoPath } from '../people/export.slot';
import { ratesPath, ratesQueryKey, type Rate } from '../rates/rates';
import { settingsPath, settingsQueryKey, type Settings } from '../roles/roles';
import { claimsPath, claimsQueryKey, type Claim } from '../claims/claims';
import { personPeriodCarried, personPeriodDue, periodsPath, periodsQueryKey, type Period } from './periods';

// The period export button: downloads the period figures as CSV — person, period, figure (the person's due-total
// for it) and carried, as the person's row shows them — one line per person and period, people in list order
// (retired people included, shown or not) and periods in the order added. Quoting and line ends as the people
// export; its inputs are re-read from the store when pressed, as the people export's.
function ExportPeriods() {
  const [user] = useCurrentUser();
  const [sheet] = useCurrentSheet();
  const queryClient = useQueryClient();
  if (!user || !sheet) return null;
  const download = async () => {
    const [info, people, claims, rates, periods, settings] = await Promise.all([
      readFresh<SheetInfo>(queryClient, sheetQueryKey(sheet), sheetInfoPath(sheet)),
      readFresh<Person[]>(queryClient, peopleQueryKey(sheet), peoplePath(sheet)),
      readFresh<Claim[]>(queryClient, claimsQueryKey(sheet), claimsPath(sheet)),
      readFresh<Rate[]>(queryClient, ratesQueryKey(sheet), ratesPath(sheet)),
      readFresh<Period[]>(queryClient, periodsQueryKey(sheet), periodsPath(sheet)),
      readFresh<Settings>(queryClient, settingsQueryKey(sheet), settingsPath(sheet)),
    ]);
    const today = figureToday(info.today);
    // The sheet's periods come by from-date; ids are assigned in the order they were added.
    const added = [...periods].sort((a, b) => a.id - b.id);
    const lines = [['person', 'period', 'figure', 'carried']];
    for (const p of people) {
      for (const q of added) {
        lines.push([p.name, q.name,
          personPeriodDue(q, p, people, claims, rates, settings, today),
          personPeriodCarried(q, periods, p, people, claims, rates, settings, today)]);
      }
    }
    const csv = lines.map((l) => l.map(csvValue).join(',') + '\n').join('');
    const url = URL.createObjectURL(new Blob([csv], { type: 'text/csv' }));
    const a = document.createElement('a');
    a.href = url;
    a.download = `periods-${sheet}.csv`;
    document.body.appendChild(a);
    a.click();
    a.remove();
    setTimeout(() => URL.revokeObjectURL(url), 1000);
  };
  return (
    <button type="button" data-testid="export-periods" onClick={() => { void download(); }}>
      Export periods (CSV)
    </button>
  );
}

export const contribution = HomeMain.fill({ order: 19.05, Component: ExportPeriods });
import { useState } from 'react';
import { HomeMain } from '../../slots/defs/homeMain';
import { useCurrentSheet, useCurrentUser } from '../session/session';
import { useClaims } from '../claims/claims';
import { policyVersionOn, useSettings } from './roles';

// The policy versions, shown once the button is pressed: one line per version, oldest first,
// <version> <from-date or start> <key>=<value> <count of claims (DELETED ones left out) whose policy version it is>.
function PolicyVersions() {
  const [user] = useCurrentUser();
  const [sheet] = useCurrentSheet();
  const settings = useSettings();
  const claims = useClaims();
  const [shown, setShown] = useState(false);
  if (!user || !sheet) return null;
  const counted = (claims.data ?? []).filter((c) => c.status !== 'DELETED');
  const lines = (settings.data?.policyLog ?? []).map((v, i) => {
    const count = counted.filter((c) => policyVersionOn(settings.data, c.date) === i + 1).length;
    return `${i + 1} ${v.from ?? 'start'} ${v.key}=${v.value ?? ''} ${count}`;
  });
  return (
    <section data-testid="policy">
      <button type="button" data-testid="policy-show" onClick={() => setShown(true)}>
        Show policy versions
      </button>
      {shown && (
        <ul>
          {lines.map((l) => <li key={l} data-testid="policy-line">{l}</li>)}
        </ul>
      )}
    </section>
  );
}

export const contribution = HomeMain.fill({ order: 34.7, Component: PolicyVersions });
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { useCurrentSheet } from '../session/session';

/** A user name's role on the sheet: clerk, steward, viewer or restricted. A name with none is a clerk. */
export type Role = { user: string; role: string };

/** The sheet's settings: its clerk limit with two decimals (null when there is none) and its floor with two
 *  decimals (a claim's live due is at least it), and its terms in days (a claim is due by its date plus them), and its late percent with two decimals (an overdue claim's due gains,
 *  for each full 30 days overdue, the one in force on that boundary date of its figure), and its policy date (YYYY-MM-DD; "" when blank: the sheet's today — a claim
 *  dated before it rounds half up, one on or after it half to even), and its period numbering from (YYYY-MM-DD; "" when off — while the sheet's today is
 *  on or after it, a claim opened is numbered within its period), and the own terms in days of grades A, B and C ("" when the
 *  grade uses the sheet's terms; a claim's due-by is fixed when it is created, from its person's grade on its date), and its cap with
 *  two decimals ("" when there is none — a person's due-total is at most the one in force on the date of their latest claim that counts), and its proof threshold with two decimals ("" when there is none — a claim whose due is
 *  above the one in force on its date cannot be settled or approved without a proof), and its grace days ("" when off; not dated), and its note threshold with two decimals ("" when there is none — a claim whose due is
 *  above the one in force on its date cannot be opened with an empty note), and its entry date (YYYY-MM-DD; "" when off; not dated — while it is set, a new claim left without a date is dated it in place of the sheet's today), and the grace days of grades A, B and C ("" when none — an overdue claim's lateness counts from its due-by plus those of its person's grade on its date, in force on its date), and the proof thresholds of grades A, B and C with two decimals ("" when none — a claim of its person's grade on its date uses the one in force then in place of the sheet's), and its pot with two decimals ("" when there is none; not dated — shared out among the members of each balanced pool by their shares), and its parent sheet's id ("" when none; not dated — a grade with no rate in force on a date takes the parent's, then its parent's, up to three levels up), and its fiscal year start month (1 to 12; "1" unless set; not dated — a fiscal year starts on its first day in that month and is named FY<yyyy> by the calendar year that day falls in), and its alert threshold with two decimals ("" when off; not dated — a person whose due-total goes above it is alerted in the audit), and its rounding mode (half-up or half-even; "" when none — a claim with one in force on the date it rounds by rounds by it, else by the policy date), and its review threshold with two decimals ("" when there is none — a claim whose due is above the one in force on its date goes to REVIEW when opened), and its escalation gap in days ("" when off; not dated — reminding a claim whose previous reminder was at least that many days before the sheet's today escalates it, once per claim), and its review SLA in days ("" when none; not dated — a REVIEW claim whose review day plus that many days is before the sheet's today is late), and its proof kinds (comma separated; "" when none; not dated — while set, a claim whose due is above its proof threshold needs a proof of each to be settled or approved), and the clerk limits of grades A, B and C with two decimals ("" when none — a claim of its person's grade on its date uses the one in force on its date in place of the sheet's in force then), and its default grade (A, B or C; "" when blank, meaning A; not dated — a person added by the quick-add bar, or by an import line with a blank grade, gets it), and its score thresholds, mid and high (whole numbers; "" when blank; not dated — while both are set, each person shows a band). Each of those is the value in force on the
 *  sheet's today; `dated` holds the values recorded for each setting that carries a figure, by key (floor, late-pct,
 *  terms, terms-A/B/C, clerk-limit, clerk-limit-A/B/C, cap, proof-threshold, note-threshold, grace-A/B/C, proof-threshold-A/B/C, rounding, review-threshold), each from its from-date on (null: from the beginning of time; a null value is blank). */
export type Settings = { clerkLimit: string | null; floor: string; terms: string;
  latePct: string; policyDate: string; periodNumberingFrom: string;
  termsA: string; termsB: string; termsC: string; cap: string; proofThreshold: string;
  dated: Record<string, { from: string | null; value: string | null }[]>;
  permOpen: string; permSettle: string; permVoid: string; permReassign: string; permClose: string; permReopen: string; permToday: string;
  graceDays: string; noteThreshold: string; entryDate: string;
  graceA: string; graceB: string; graceC: string;
  proofThresholdA: string; proofThresholdB: string; proofThresholdC: string; pot: string; parent: string;
  fiscalStartMonth: string; alertThreshold: string; rounding: string; reviewThreshold: string;
  escalateAfter: string; reviewSla: string; proofKinds: string; defaultGrade: string;
  clerkLimitA: string; clerkLimitB: string; clerkLimitC: string;
  scoreMid: string; scoreHigh: string; scoreLog: string; maxOpen: string; pendingSla: string;
  /** The policy versions (each change to the rounding mode, floor, cap, terms, late percent or clerk limit), in the
   *  order made, numbered from 1: each one's from-date (null: none — it counts always). */
  policyVersions: (string | null)[];
  /** The same policy versions, each with the setting it changed and the value set (null: blank). */
  policyLog: { from: string | null; key: string; value: string | null }[] };

/** The value of a dated setting in force on a date (YYYY-MM-DD): the one recorded with the latest from-date on or
 *  before it, else `start` (the sheet's starting value). */
export function settingOn(settings: Settings | undefined, key: string, date: string, start: string): string {
  let found: { from: string | null; value: string | null } | undefined;
  for (const d of settings?.dated?.[key] ?? []) {
    if (d.from !== null && d.from > date) continue;
    if (!found || (found.from ?? '') <= (d.from ?? '')) found = d;
  }
  return found ? (found.value ?? start) : start;
}

/** The current policy version: how many have been made (0: none). */
export function policyVersion(settings: Settings | undefined): number {
  return settings?.policyVersions?.length ?? 0;
}

/** The policy version in force on a date (YYYY-MM-DD): how many versions have a from-date on or before it, or none. */
export function policyVersionOn(settings: Settings | undefined, date: string): number {
  return (settings?.policyVersions ?? []).filter((from) => from === null || from <= date).length;
}

/** The terms a sheet starts at, in days. */
export const DEFAULT_TERMS = '14';

export const rolesQueryKey = (sheetId: string) => ['sheet', sheetId, 'roles'] as const;
export const rolesPath = (sheetId: string) => `/api/sheets/${encodeURIComponent(sheetId)}/roles`;

export const settingsQueryKey = (sheetId: string) => ['sheet', sheetId, 'settings'] as const;
export const settingsPath = (sheetId: string) => `/api/sheets/${encodeURIComponent(sheetId)}/settings`;

/** The user names given a role on the sheet, by name. */
export function useRoles() {
  const [sheet] = useCurrentSheet();
  return useQuery({
    queryKey: rolesQueryKey(sheet ?? ''),
    queryFn: () => getJson<Role[]>(rolesPath(sheet ?? '')),
    enabled: !!sheet,
  });
}

export function useSettings() {
  const [sheet] = useCurrentSheet();
  return useQuery({
    queryKey: settingsQueryKey(sheet ?? ''),
    queryFn: () => getJson<Settings>(settingsPath(sheet ?? '')),
    enabled: !!sheet,
  });
}

/** The steward role delegated by a steward (`by`) to a user name, from `from` to `to` (YYYY-MM-DD), inclusive, by
 *  the sheet's today: while today is inside it the user acts as a steward in every rule. */
export type Delegation = { user: string; by: string; from: string; to: string };

export const delegationsQueryKey = (sheetId: string) => ['sheet', sheetId, 'delegations'] as const;
export const delegationsPath = (sheetId: string) => `/api/sheets/${encodeURIComponent(sheetId)}/delegations`;

/** The delegations made on the sheet, oldest first. */
export function useDelegations() {
  const [sheet] = useCurrentSheet();
  return useQuery({
    queryKey: delegationsQueryKey(sheet ?? ''),
    queryFn: () => getJson<Delegation[]>(delegationsPath(sheet ?? '')),
    enabled: !!sheet,
  });
}
